            if (units >= 10) total = units * 250L;
            else if (units >= 5) total = units * 300L;
            else total = units * 350L;
            if (plan == Plan.MEMBER) total = total * 90 / 100;
        }
        return plan.name() + "|" + units + "|" + total;
